	@Test
	void maskStrataRequireCanonicalOrderAndPreserveEveryBoundDomain() {
		FrontierLayout layout = FrontierLayout.of("x", "y");
		long[] reverseOrder = { 0b11L, 0b01L };
		assertThrows(IllegalArgumentException.class, () -> FrontierMaskStrata.of(layout, 2, reverseOrder));
		reverseOrder[0] = 0L;
		FrontierMaskStrata masks = FrontierMaskStrata.of(layout, 2, new long[] { 0b01L, 0b11L });

		assertEquals(2, masks.stratumCount());
		assertEquals(1, masks.wordCount());
		assertEquals(0b01L, masks.word(0, 0));
		assertEquals(0b11L, masks.word(1, 0));
		assertTrue(masks.isBound(0, 0));
		assertTrue(!masks.isBound(0, 1));
		assertTrue(masks.isBound(1, 1));
		assertThrows(IllegalArgumentException.class,
				() -> FrontierMaskStrata.of(layout, 2, new long[] { 0b01L, 0b01L }));
		assertThrows(IllegalArgumentException.class,
				() -> FrontierMaskStrata.of(layout, 1, new long[] { 0b100L }));
		assertThrows(IllegalArgumentException.class,
				() -> FrontierMaskStrata.of(layout, 2, new long[] { 0b01L }));
		assertEquals(
				FrontierMaskStrata.of(FrontierLayout.empty(), 1, new long[0]),
				FrontierMaskStrata.of(FrontierLayout.empty(), 1, new long[0]));
	}

