	@Test
	void liveHandleObjectsAreChargedToTheQueryBudget() {
		FrontierMaskStrata masks = FrontierMaskStrata.of(FrontierLayout.of("x"), 1, new long[] { 1L });
		FrontierStateKey key = key(masks, FrontierLaneFamily.DESIGN, 0);

		try (FrontierStateArena arena = new FrontierStateArena(64 * 1024L)) {
			long baseline = arena.allocatedBytes();
			try (FrontierMemoryReservation reservation = arena.reserveTemporary(
					0L,
					FrontierMemoryPurpose.BRIDGE_EMISSION)) {
				assertTrue(arena.allocatedBytes() > baseline);
				assertTrue(arena.temporaryReservedBytes() > 0L);
			}
			assertEquals(baseline, arena.allocatedBytes());

			arena.declareCanonicalStates(key);
			long writerBaseline = arena.allocatedBytes();
			FrontierPayloadWriter writer = arena.newPayloadWriter(key, new int[] { 1 }, new int[] { 0 });
			long bulkWriterBytes = FrontierPayloadBlock.retainedBytes(
					masks,
					new int[] { 1 },
					new int[] { 0 })
					+ arrayBytes(1, Byte.BYTES)
					+ arrayBytes(0, Byte.BYTES);
			assertTrue(arena.temporaryReservedBytes() > bulkWriterBytes);
			writer.putExact(0, 0, 1.0d, new long[] { 11L }, 0);
			EvidenceStateRef state = arena.internPayload(
					key,
					EvidenceStateSummary.exact(1.0d),
					FrontierStateOperation.EXACT_LEAF,
					null,
					null,
					1,
					writer);
			assertTrue(arena.allocatedBytes() > writerBaseline);

			long residentBaseline = arena.allocatedBytes();
			try (FrontierPayloadLease lease = arena.openPayload(state)) {
				assertTrue(arena.allocatedBytes() > residentBaseline);
				assertTrue(arena.temporaryReservedBytes() > 0L);
				assertEquals(1.0d, lease.exactWeight(0, 0));
			}
			assertEquals(residentBaseline, arena.allocatedBytes());
		}
	}

	@Test
	void arenaCloseRejectsOutstandingChildrenWithoutStrandingThem() {
		FrontierMaskStrata masks = FrontierMaskStrata.of(FrontierLayout.of("x"), 1, new long[] { 1L });
		FrontierStateKey key = key(masks, FrontierLaneFamily.DESIGN, 0);
		FrontierStateArena arena = new FrontierStateArena(64 * 1024L);
		arena.declareCanonicalStates(key);
		FrontierPayloadWriter writer = arena.newPayloadWriter(key, new int[] { 1 }, new int[] { 0 });
		writer.putExact(0, 0, 1.0d, new long[] { 11L }, 0);
		EvidenceStateRef state = arena.internPayload(
				key,
				EvidenceStateSummary.exact(1.0d),
				FrontierStateOperation.EXACT_LEAF,
				null,
				null,
				1,
				writer);

		FrontierPayloadLease lease = arena.openPayload(state);
		assertThrows(IllegalStateException.class, arena::close);
		assertEquals(1.0d, lease.exactWeight(0, 0));
		lease.close();

		FrontierMemoryReservation reservation = arena.reserveTemporary(
				1L,
				FrontierMemoryPurpose.BRIDGE_EMISSION);
		assertThrows(IllegalStateException.class, arena::close);
		reservation.close();
		arena.close();
		assertEquals(0L, arena.allocatedBytes());
	}

